INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count, international_benchmark
) VALUES
('ENG-1112-SYN-01', 'English Literacy', 'synthesis', '11-12', 'standard', 'Epistemological Text X: "Empirical verificationism posits that truth assertions are meaningful strictly if they can be corroborated by isolated, sensory protocol statements." Epistemological Text Y: "Quine''s holism demonstrates that our statements about the external world face the tribunal of sense experience not individually, but only as an interconnected corporate body of beliefs." How does Text Y challenge Text X?', '[{"text":"By affirming that protocol statements possess unassailable Cartesian certainty.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"By arguing that sensory observation plays zero functional role in scientific paradigm shifts.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"By asserting that formal mathematical logic is inherently self-contradictory.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"By demonstrating that theoretical webs of belief cannot be parsed into isolated, independently verifiable observation statements.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing verificationist logical positivism with Quinean confirmation holism.', 'Text Y argues that ideas face experience as a connected web, not in single isolated statements.', 1.5, 1.2, 0.25, true, 0, 'IB Diploma Theory of Knowledge / Cambridge A-Level'),
('ENG-1112-SYN-02', 'English Literacy', 'synthesis', '11-12', 'standard', 'Comparative Poetics: "While Romantic naturalism constructed the wilderness as an uncorrupted, sublime cathedral, modern ecocritical theory deconstructs this binary, arguing that the myth of ''pure nature'' abdicates human ecological accountability in hybrid industrial anthropocenes." What conceptual shift is articulated?', '[{"text":"The validation of Romantic sublime theology as the sole effective basis for climate legislation.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"A total rejection of industrial manufacturing in favor of pre-industrial agrarian subsistence.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"A transition from idealizing nature as an external, pristine sanctuary to recognizing humanity''s inescapable entwinement within anthropogenically altered ecosystems.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"A proof that literary criticism has zero intersection with ecological sciences.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing Romantic aesthetic philosophy with contemporary Anthropocene ecocriticism.', 'Look for the shift: from nature as an "external pure cathedral" to nature as "inescapably entangled with human impact".', 1.55, 1.3, 0.25, true, 0, 'Singapore GCE A-Level H2 Literature in English'),
('ENG-1112-SYN-03', 'English Literacy', 'synthesis', '11-12', 'standard', 'Neuroscience Monograph: "Functional MRI studies demonstrate that chronic socio-economic precarity floods the prefrontal cortex with cortisol, impairing executive cognitive control and working memory capacity." Public Policy Analysis: "Social welfare architectures that impose onerous administrative means-testing require immense cognitive bandwidth, causing vulnerable applicants to frequently miss compliance deadlines." What synthesized policy critique emerges?', '[{"text":"Eliminating cortisol from the bloodstream completely cures chronic socio-economic inequality.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Welfare applicants possess innate biological deficits in mathematical logic that make paperwork impossible.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Complex administrative compliance hurdles paradoxically tax the very cognitive executive bandwidth that chronic poverty biologically impairs, creating systemic traps of exclusion.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Executive function has zero measurable bearing on bureaucratic form completion.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing neuroendocrinology of chronic stress with structural public policy critique.', 'How does stressful poverty reduce brain bandwidth, and how does heavy paperwork demand that very same bandwidth?', 1.55, 1.2, 0.25, true, 0, 'AP English Language and Composition'),
('ENG-1112-SYN-04', 'English Literacy', 'synthesis', '11-12', 'standard', 'Biomedical Ethics Text: "The principle of non-maleficence mandates that physicians must never administer treatments whose anticipated harms exceed anticipated benefits." Public Health Epidemiology: "During catastrophic infectious pandemics, mass mandatory quarantine restricts individual civil liberties and inflicts psychological harm to prevent systemic hospital collapse." How are these principles synthesized in public health bioethics?', '[{"text":"The ethical focus shifts from individual clinical non-maleficence to utilitarian population-level harm minimization and collective preservation.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Individual civil liberties must always supersede communal survival regardless of mortality rates.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Physicians are legally prohibited from practicing epidemiology during respiratory pandemics.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Infectious pandemics eliminate all need for bioethical deliberation.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing clinical bioethical deontological principles with population utilitarian epidemiology.', 'Notice the pivot from treating one single patient to protecting the whole community.', 1.5, 1.1, 0.25, true, 0, 'CBSE Class 12 English Core & Ethics'),
('ENG-1112-SYN-05', 'English Literacy', 'synthesis', '11-12', 'advanced', 'Historical Text Alpha: "In the 18th century, Adam Smith argued that the division of labor maximizes industrial output through extreme task specialization." Critical Text Beta: "Karl Marx demonstrated that the radical division of labor alienates the worker from the finished product, the process of labor, their fellow workers, and their human creative essence (species-being)." What comprehensive dialectic encapsulates both perspectives?', '[{"text":"Smith and Marx agreed that factory automation would eliminate the need for human employment by 1900.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Industrial division of labor produces unprecedented physical and material productivity, but does so at the psychological cost of existential labor alienation and worker deskilling.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Labor specialization enhances human spiritual happiness and eradicates workplace boredom.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Manual handicraft guilds produce higher industrial output than mechanized assembly lines.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing classical political economy (Smith) with critical Marxist labor alienation theory.', 'Balance the massive output gains of specialization with the psychological alienation of the worker.', 1.6, 1.4, 0.25, true, 0, 'IB Diploma Literature & Philosophy Higher Level'),
('ENG-1112-SYN-06', 'English Literacy', 'synthesis', '11-12', 'advanced', 'Ecological Economics Paper: "The Jevons Paradox establishes that technological improvements in resource efficiency, by reducing the effective cost of consumption, often lead to a net increase in total resource consumption rather than a decrease." Energy Policy Report: "LED lightbulbs use 85% less electricity than incandescent bulbs; however, aggregate municipal outdoor nighttime illumination grew by 60% following LED adoption." How does the lighting report instantiate the Jevons Paradox?', '[{"text":"LED lightbulbs consume more wattage per hour than antique filament bulbs.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Efficiency gains made nighttime lighting so economically cheap that cities massively expanded illumination, offsetting expected energy conservation.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"The paradox was disproven because overall electrical generation was completely halted.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Cities adopted LED lighting exclusively to improve astronomy conditions for urban observatories.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing macroeconomic resource paradoxes with empirical energy consumption trends.', 'Notice how making lighting 85% cheaper led people to install 60% more lights.', 1.65, 1.5, 0.25, true, 0, 'Cambridge International A-Level Economics & English'),
('ENG-1112-SYN-07', 'English Literacy', 'synthesis', '11-12', 'advanced', 'Semiotics of Architecture: "Panoptic spatial design utilizes central observation towers to cultivate internal self-policing; individuals behave as if perpetually watched, internalizing external surveillance." Digital Culture Analysis: "Contemporary social media participants continuously curate their speech, appearance, and opinions anticipating algorithmic rating and peer scrutiny." What sociological synthesis connects these domains?', '[{"text":"The physical architectural panopticon has evolved into a digital, decentralized algorithmic panopticon, where citizens actively internalize and perform perpetual self-surveillance.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Physical prison towers are structurally identical to digital fiber-optic cables.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Social media platforms have eradicated all forms of social conformity and self-censorship.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Algorithmic curation operates entirely without the awareness or participation of users.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing Foucault''s panopticism with algorithmic social media self-policing.', 'Look for how physical surveillance towers became psychological self-surveillance online.', 1.65, 1.5, 0.25, true, 0, 'Singapore GCE A-Level H2 General Paper'),
('ENG-1112-SYN-08', 'English Literacy', 'synthesis', '11-12', 'olympiad', 'Epigenetics Study: "Exposure to severe famine induces DNA methylation changes at the IGF2 locus that alter metabolic thrift, alterations that persist and remain biologically detectable in grandchildren two generations later." Sociology of Inequality: "Generational trauma and historical structural poverty produce persistent health disparities across marginalized communities that resist simple lifestyle interventions." What paradigm shift in social medicine is forged by this synthesis?', '[{"text":"Historical socioeconomic trauma physically alters biological gene expression across generational lineages, establishing that structural injustice becomes biologically embodied.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"Famine eradicated all genetic variations across human ancestral lineages.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Socioeconomic inequality is purely a cultural narrative with zero biological or medical correlates.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Epigenetic methylation can be reversed instantly through positive psychological affirmations.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing transgenerational molecular epigenetics with sociological structural violence.', 'How does trauma get written into DNA and passed down across two generations?', 1.7, 1.7, 0.25, true, 0, 'Singapore English Olympiad Senior Division Finals'),
('ENG-1112-SYN-09', 'English Literacy', 'synthesis', '11-12', 'olympiad', 'Linguistic Philosophy: "Wittgenstein''s ''private language argument'' demonstrates that a language decipherable by only one individual is logically impossible, because language rules require communal verification to distinguish correct usage from mistaken impressions." Cognitive AI Debate: "Proponents of isolated synthetic machine consciousness claim that an isolated neural network can invent its own private semantic understanding in a vacuum." How does Wittgenstein''s argument undermine the isolated AI claim?', '[{"text":"Machines cannot process electrical currents without private linguistic dictionaries.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Wittgenstein proved that artificial neural networks cannot perform matrix multiplication.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"True semantic meaning and rule-following inherently require social, intersubjective communal verification; an isolated system can generate mechanical outputs but cannot establish genuine linguistic meaning.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]},{"text":"All linguistic rules are biological instincts encoded in mammalian DNA.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]}]'::jsonb, 'Synthesizing Wittgensteinian philosophy of language with contemporary cognitive AI theory.', 'Can meaning exist for a solitary entity with no community to check if a rule is being followed?', 1.75, 1.8, 0.25, true, 0, 'Oxford / Cambridge Undergraduate Admissions Test (ELAT / TSA)'),
('ENG-1112-SYN-10', 'English Literacy', 'synthesis', '11-12', 'olympiad', 'Post-Colonial Theory: "Frantz Fanon posits that colonization imposes an inferiority complex upon the colonized by forcing them to define their humanity through the linguistic and cultural mirror of the colonizer." Decolonial Pedagogy: "Educational reform in formerly colonized nations must transcend replacing foreign textbooks with local ones; it requires unlearning the epistemological hierarchy that devalues indigenous ways of knowing." What overarching decolonial synthesis is articulated?', '[{"text":"Replacing foreign textbooks with domestic translations instantly achieves complete decolonization.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Decolonial pedagogy mandates the total burning of all printed historical archives.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Fanon argued that language has zero impact on psychological identity or cultural self-worth.","correct":false,"evidence":[{"competency":"synthesis","earnedWeight":0}]},{"text":"Genuine decolonization is not merely a political transfer of state power, but a radical epistemological emancipation that dismantles internalized hierarchies of cultural and intellectual validity.","correct":true,"evidence":[{"competency":"synthesis","earnedWeight":1}]}]'::jsonb, 'Synthesizing Fanonian psycho-colonial theory with radical decolonial epistemological pedagogy.', 'Notice: true decolonization requires dismantling the internalized hierarchy of what counts as knowledge.', 1.8, 1.8, 0.25, true, 0, 'IB Diploma English A Literature High Distinction'),
('ENG-1112-EVL-01', 'English Literacy', 'evaluatingReflecting', '11-12', 'standard', '"The essayist employs an ironically understated, clinically sterile vocabulary to recount catastrophic wartime civilian displacement." What stylistic dissonance is generated, and to what deliberate ethical end?', '[{"text":"The sterile vocabulary proves the author lacked first-hand testimony of the events described.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The jarring contrast between human devastation and bureaucratic sterility powerfully indicts the dehumanizing, technocratic detachment of modern warfare.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The understated phrasing aims to minimize reader anxiety so the publication passes military censors.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"It transforms the historical essay into an operational handbook for battlefield logistics.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating stylistic dissonance, understated irony, and rhetorical indictment in war literature.', 'Why talk about devastation with cold, clinical words? To show how modern war treats people like cold numbers.', 1.45, 1.1, 0.25, true, 0, 'Cambridge International A-Level Literature'),
('ENG-1112-EVL-02', 'English Literacy', 'evaluatingReflecting', '11-12', 'standard', '"When the narrative perspective shifts abruptly from panoramic third-person omniscience into fractured, unreliable first-person interior monologue, what psychometric and interpretive disruption occurs for the reader?"', '[{"text":"The reader is abruptly stripped of objective authoritative certainty and forced to navigate subjective cognitive distortion and epistemic vulnerability.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"The plot chronology halts permanently to insert an expository biographical footnote.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The linguistic register simplifies to accommodate juvenile demographic readers.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The author signals that the preceding narrative was entirely a dream sequence.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing interpretive destabilization through shifting narrative perspective and unreliable narration.', 'Going from an all-knowing narrator to a fractured first-person mind strips away all objective certainty.', 1.5, 1.2, 0.25, true, 0, 'IB Diploma Language A Literature'),
('ENG-1112-EVL-03', 'English Literacy', 'evaluatingReflecting', '11-12', 'standard', 'In analyzing an editorial on biotechnology, a scholar observes: "The author frames human gene editing using religious idioms of ''playing God'' and ''violating sacred biological sanctity,'' while systematically ignoring empirical clinical safety trial data." What rhetorical strategy is exposed?', '[{"text":"An objective presentation of peer-reviewed clinical cardiology trials.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A rigorous mathematical proof of cellular enzymatic instability.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Deploying metaphysical taboos and dogmatic emotional heuristics to preemptively close empirical scientific debate.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A defense of secular pharmaceutical patent monopolies.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing metaphysical taboos and dogmatic rhetoric in scientific bioethics debates.', 'Notice how religious idioms ("playing God") are used to bypass actual clinical data.', 1.5, 1.2, 0.25, true, 0, 'AP English Language and Composition'),
('ENG-1112-EVL-04', 'English Literacy', 'evaluatingReflecting', '11-12', 'standard', '"The historian concludes: ''The monarch did not build the grand palace to celebrate his sovereign security, but to mask his profound vulnerability; its monumental marble colonnades were an architectural scream defying his imminent obsolescence.''" What psychological reinterpretation of monumentality is offered?', '[{"text":"A proof that classical architecture guarantees geopolitical military dominance.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A literal engineering critique of marble quarry extraction techniques.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Praise for the monarch''s enlightened economic patronage of stonecutters.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Monumental grandeur as compensatory overcompensation: using excessive physical majesty to conceal fragile political precarity.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Interpreting architectural monumentality as compensatory psychological defensiveness.', 'The palace was built not because he felt safe, but to hide that he was weak and doomed.', 1.55, 1.3, 0.25, true, 0, 'Singapore GCE A-Level H2 Literature'),
('ENG-1112-EVL-05', 'English Literacy', 'evaluatingReflecting', '11-12', 'advanced', '"In analyzing the corporate sustainability manifesto, the critic remarks: ''The manifesto dedicates forty pages to carbon offset tree-planting photo-essays, while confining its twenty-fold expansion of fossil-fuel deepwater exploration to a three-line footnote.'' How does the critic expose corporate greenwashing?"', '[{"text":"By commending the company''s transparent disclosure of exploratory drilling costs.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"By proving that tree-planting is biologically harmful to atmospheric oxygen levels.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"By demonstrating severe proportional asymmetry: elevating symbolic public relations gestures while burying catastrophic core extractive commitments.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"By verifying that footnote typography violates international copyright law.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Deconstructing greenwashing through structural rhetorical asymmetry and document analysis.', '40 pages of tree photos vs a 3-line footnote for massive oil drilling: massive visual asymmetry.', 1.6, 1.4, 0.25, true, 0, 'Cambridge International A-Level General Paper'),
('ENG-1112-EVL-06', 'English Literacy', 'evaluatingReflecting', '11-12', 'advanced', '"The post-colonial critic notes: ''The novelist adopts the elevated imperial register of Victorian English only to deliberately shatter its syntactical balance with indigenous Creole idioms and polyvocal cadences.'' What subversive aesthetic objective is accomplished?"', '[{"text":"An inadvertent error caused by the author''s imperfect grasp of standard English grammar.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"Linguistic appropriation and decolonization: weaponizing the colonizer''s prestigious tongue against itself to validate suppressed indigenous rhythms.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A commercial concession to increase mass paperback sales in Victorian London.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A pedagogical manual designed to eradicate regional Caribbean dialects.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing post-colonial counter-discourse, linguistic subversion, and polyvocality.', 'Why write in high Victorian style only to break it open with Creole idioms? To decolonize the language from within.', 1.65, 1.5, 0.25, true, 0, 'IB Diploma English A Literature Higher Level'),
('ENG-1112-EVL-07', 'English Literacy', 'evaluatingReflecting', '11-12', 'advanced', '"When the legal philosopher characterizes contract law not as ''the neutral realization of private autonomy,'' but as ''the state-sanctioned formalization of pre-existing economic disparities,'' what foundational legal fiction is being dismantled?"', '[{"text":"The historical connection between Roman contract law and modern maritime commerce.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The physical validity of written ink signatures on commercial paper.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The authority of appellate judges to interpret statutory municipal tax codes.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The presumption that contracting parties possess equal bargaining power in market transactions.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Critiquing formal legal equality and the myth of equal bargaining power in contract theory.', 'It takes down the idea that both sides entering a contract have equal freedom and power.', 1.65, 1.5, 0.25, true, 0, 'Singapore GCE A-Level H2 General Paper'),
('ENG-1112-EVL-08', 'English Literacy', 'evaluatingReflecting', '11-12', 'olympiad', '"The dramatist constructs the play so that every character''s impassioned ideological defense of their actions is shown to be an elaborate, self-deluding rationalization for base material self-interest. What overarching cynical worldview permeates the theatrical dramaturgy?"', '[{"text":"A corrosive hermeneutics of suspicion: positing that moral ideals are merely post-hoc intellectual disguises for primal animal egoism and resource acquisition.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A celebration of transcendent altruism and selfless human martyrdom.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A classical tragedy validating the absolute divine justice of mythological deities.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A pedagogical demonstration of classical rhetorical elocution techniques.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Analyzing the hermeneutics of suspicion and moral disillusionment in dramatic literature.', 'If every moral speech is really just an excuse for selfish greed, what worldview is that?', 1.75, 1.7, 0.25, true, 0, 'Oxford English Literature Admissions Test (ELAT)'),
('ENG-1112-EVL-09', 'English Literacy', 'evaluatingReflecting', '11-12', 'olympiad', '"The essayist deconstructs modern wellness culture, asserting: ''By reframing systemic institutional burnout as a personal psychological failure solvable through commercial mindfulness apps, corporate capitalism commodifies the very exhaustion it produces.'' What profound ideological operation is diagnosed?"', '[{"text":"A technical critique of digital smartphone application code architecture.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A clinical trial proving that mindfulness meditation cures all autoimmune diseases.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An endorsement of corporate human resource wellness subsidies.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"The depoliticization and privatization of structural exploitation, turning worker exhaustion into a lucrative secondary market for therapeutic consumerism.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]}]'::jsonb, 'Deconstructing the neoliberal commodification of wellness and structural depoliticization.', 'Notice: taking systemic overwork and selling back apps to "fix your personal failure".', 1.8, 1.8, 0.25, true, 0, 'Cambridge A-Level Distinction / Ivy League Diagnostic'),
('ENG-1112-EVL-10', 'English Literacy', 'evaluatingReflecting', '11-12', 'olympiad', '"In reflecting on the Holocaust, philosopher Theodor Adorno famously proclaimed: ''To write poetry after Auschwitz is barbaric.'' What profound crisis of culture, representation, and aesthetics does this aphorism crystallize?"', '[{"text":"The devastating realization that traditional humanistic culture failed to prevent absolute industrial slaughter, rendering traditional aesthetic pleasure morally suspect and ethically compromised.","correct":true,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":1}]},{"text":"A legal prohibition banning the printing of rhymed verse in post-war Germany.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"A claim that visual painting is superior to written literature in commemorating tragedy.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]},{"text":"An assertion that the German language lacked sufficient vocabulary for poetic composition.","correct":false,"evidence":[{"competency":"evaluatingReflecting","earnedWeight":0}]}]'::jsonb, 'Evaluating Adorno''s philosophical critique of culture and aesthetics in the shadow of historical catastrophe.', 'How can culture claim to be elevated and beautiful when the very society that produced it created industrial slaughter?', 1.85, 1.9, 0.25, true, 0, 'World Universities Debating Championship / High Honors Literature')
